package doctor

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/githook"
	"github.com/punt-labs/ethos/v4/plugin/hooks"
	"github.com/stretchr/testify/require"
)

// PROBE A: dormant repo (no marker) + a foreign shell pre-commit hook, on a
// host with no git. Documented state 2 says PASS "not enabled here".
func TestProbe_DormantGitless(t *testing.T) {
	dir := t.TempDir()
	h := filepath.Join(dir, ".git", "hooks")
	require.NoError(t, os.MkdirAll(h, 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(h, "pre-commit"),
		[]byte("#!/bin/sh\ntrue\n"), 0o755))
	t.Setenv("PATH", t.TempDir()) // no git
	r := CheckSealHook(dir)
	t.Logf("PROBE A status=%s detail=%s", r.Status, r.Detail)
}

// PROBE B: enabled repo, real ethos section chained after a host hook whose
// own logic depends on an environment variable the sandbox strips.
func TestProbe_HostPrefixEnvDependent(t *testing.T) {
	dir := t.TempDir()
	h := filepath.Join(dir, ".git", "hooks")
	require.NoError(t, os.MkdirAll(h, 0o755))
	host := "#!/bin/sh\n[ -n \"$MY_CI_TOKEN\" ] || { echo 'host hook: missing token' >&2; exit 1; }\n"
	require.NoError(t, os.WriteFile(filepath.Join(h, "pre-commit"), []byte(host), 0o755))
	_, err := githook.Chain(filepath.Join(h, "pre-commit"), hooks.PreCommit, hooks.SealTag, hooks.SealIdent)
	require.NoError(t, err)
	require.NoError(t, os.MkdirAll(filepath.Join(dir, ".punt-labs", "ethos"), 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(dir, ".punt-labs", "ethos", "enabled"), nil, 0o644))
	t.Setenv("MY_CI_TOKEN", "present-in-the-real-environment")
	r := CheckSealHook(dir)
	t.Logf("PROBE B status=%s detail=%s", r.Status, r.Detail)
}

// PROBE C: enabled repo, real ethos section chained after a host hook that
// runs a linter which fails in an empty scratch repo but passes in the real
// one (stand-in: a command that checks for a file that exists in the real
// repo).
func TestProbe_HostPrefixRepoContentDependent(t *testing.T) {
	dir := t.TempDir()
	h := filepath.Join(dir, ".git", "hooks")
	require.NoError(t, os.MkdirAll(h, 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module x\n"), 0o644))
	host := "#!/bin/sh\n[ -f go.mod ] || { echo 'host lint: not a go repo' >&2; exit 1; }\n"
	require.NoError(t, os.WriteFile(filepath.Join(h, "pre-commit"), []byte(host), 0o755))
	_, err := githook.Chain(filepath.Join(h, "pre-commit"), hooks.PreCommit, hooks.SealTag, hooks.SealIdent)
	require.NoError(t, err)
	require.NoError(t, os.MkdirAll(filepath.Join(dir, ".punt-labs", "ethos"), 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(dir, ".punt-labs", "ethos", "enabled"), nil, 0o644))
	r := CheckSealHook(dir)
	t.Logf("PROBE C status=%s detail=%s", r.Status, r.Detail)
}

// PROBE D: does doctor EXECUTE a dormant repo's foreign host hook? A repo
// that never enabled ethos should not have its hooks run by a diagnostic.
func TestProbe_DormantRepoHookIsExecuted(t *testing.T) {
	dir := t.TempDir()
	witness := filepath.Join(t.TempDir(), "side-effect")
	h := filepath.Join(dir, ".git", "hooks")
	require.NoError(t, os.MkdirAll(h, 0o755))
	body := "#!/bin/sh\ntouch " + witness + "\n"
	require.NoError(t, os.WriteFile(filepath.Join(h, "pre-commit"), []byte(body), 0o755))
	r := CheckSealHook(dir)
	_, err := os.Stat(witness)
	t.Logf("PROBE D status=%s detail=%s sideEffectHappened=%v", r.Status, r.Detail, err == nil)
}

// PROBE E: extra args on the ethos call.
func TestProbe_ExtraArgs(t *testing.T) {
	observed, err := hookInvocationObserved(
		[]byte("#!/bin/sh\nethos audit seal --quiet\n"), []string{"audit", "seal"}, false)
	t.Logf("PROBE E observed=%v err=%v", observed, err)
}
